/* Pages for one connected practice area. Keeps the five existing mobile destinations. */
function labLesson(){if(!currentCourse().lessons.includes(labSelectedLesson))labSelectedLesson=courseFocusId();return labSelectedLesson}
function labShell(title,body,page='lab'){
 const id=labLesson();return `<div class="lab-page"><header class="lab-heading"><div><span class="eyebrow">${esc(currentCourse().name)} · Practice</span><h1>${esc(title)}</h1></div><label>Chapter<select aria-label="Practice chapter" onchange="labSelectedLesson=this.value;navigate('${page}')">${courseChapters().map(([key,name])=>`<option value="${key}" ${key===id?'selected':''}>${esc(lessonLabel(key)+' · '+name)}</option>`).join('')}</select></label></header><nav class="lab-tabs" aria-label="Practice tools">${[['lab','Practice'],['labalbum','Mistakes'],['labskills','Skills'],['labdecks','My decks'],['labcamp','Camp']].map(([key,name])=>`<button class="${page===key?'active':''}" ${page===key?'aria-current="page"':''} onclick="navigate('${key}')">${name}</button>`).join('')}</nav>${body}</div>`;
}

function labActivityTile(mode){const available=labModeAvailable(mode,labLesson());return `<button class="lab-activity" ${available?'':'disabled'} onclick="labStart('${mode}')"><span class="lab-tile-icon">${icon(['parts','transform','duel'].includes(mode)?'layers':['story','comic','scene','dialogue','cloze'].includes(mode)?'read':['sound','dictation','homophones'].includes(mode)?'sound':'write')}</span><strong>${esc(LAB_MODES[mode][0])}</strong><small>${esc(available?LAB_MODES[mode][1]:mode==='words'?'Study the characters to open this trail.':'Available with suitable material in another chapter or script.')}</small>${icon('arrow')}</button>`}

function renderLab(){
 setPracticeViewport(false);const id=labLesson(),resume=labData().runs[selectedCourseId],recommend=labAdaptiveMode(),episode=labEpisode(id),cards=uniqueCards(id),familiarCount=cards.filter(familiar).length,title=courseChapters().find(c=>c[0]===id)?.[1]||'This chapter';
 const launch=`<section class="lab-launch"><div class="lab-launch-copy"><span class="eyebrow">${esc(lessonLabel(id))} · ${cards.length} characters</span><h2>${esc(title)}</h2><p>Work through the full chapter. Try to read each character before revealing it.</p><div class="lab-launch-actions"><button class="btn primary" onclick="startSession('all','${id}')">Full chapter practice ${icon('arrow')}</button><button class="btn" onclick="startWrittenChapter('${id}')">Write to answer ${icon('write')}</button></div><div class="lab-launch-meta"><span>${familiarCount} / ${cards.length} familiar</span><button class="textbtn" onclick="openChapter('${id}')">View chapter ${icon('chevron')}</button></div></div>${cleanBuddyEnabled()?`<button class="lab-launch-buddy" aria-label="Visit companion camp" onclick="navigate('labcamp')">${companionReactionArt('ready')}</button>`:`<span class="lab-launch-glyph" lang="zh" aria-hidden="true">${esc(text(CHAPTERS.find(c=>c[0]===id)?.[3]||'学'))}</span>`}</section>`;
 const groups=[['read','Use it in a story',episode?.title||'Stories and conversations',episode?.goal||'Read a short scene and decide what to do.','story','Story mission',['comic','scene','dialogue']],['layers','Remember the shape','Parts, patterns, and lookalikes','See where a component sits and what changes the character.','parts','Build a character',['transform','duel','fonts']],['write','Practice from memory','A short mixed run','Switch between reading, shape, writing, and sentences. Misses return.','mixed','Start chapter run',['sound','dictation','cloze']]];
 $('view').innerHTML=labShell('Chapter practice',`${resume&&!resume.done?`<button class="lab-resume" onclick="labResume()"><span class="lab-resume-icon">${icon('play')}</span><span><strong>Continue ${esc(LAB_MODES[resume.mode][0])}</strong><small>${esc(lessonLabel(resume.lesson))} · ${resume.pos+1} / ${resume.queue.length}</small></span>${icon('arrow')}</button>`:''}${launch}<div class="lab-section-heading"><h2>Choose a different way</h2><span>Keep working with this chapter</span></div><div class="lab-paths">${groups.map(([glyph,label,name,description,mode,button,more])=>`<section class="lab-path"><span class="lab-path-icon">${icon(glyph)}</span><div><span class="eyebrow">${label}</span><h3>${esc(name)}</h3><p>${esc(description)}</p><div class="lab-inline"><button ${labModeAvailable(mode,id)?'':'disabled'} onclick="labStart('${mode}')">${button} ${icon('arrow')}</button>${more.map(m=>`<button ${labModeAvailable(m,id)?'':'disabled'} onclick="labStart('${m}')">${esc({comic:'Mini comic',scene:'Everyday scene',dialogue:'Dialogue',transform:'Transform',duel:'Lookalikes',fonts:'Fonts',sound:'Pinyin → character',dictation:'Listen & write',cloze:'Cloze'}[m])}</button>`).join('')}</div></div></section>`).join('')}</div><aside class="lab-recommend"><div><span class="eyebrow">From your practice</span><strong>${esc(LAB_MODES[recommend.mode][0])}</strong><p>${esc(recommend.reason)}</p></div><button class="btn" onclick="labStart('${recommend.mode}')">Practice ${icon('arrow')}</button></aside>${labGapDays()>=7&&labScopeCards(id).some(c=>state.cards[c.character]?.seen>0)?`<section class="lab-reentry"><strong>Return with familiar material</strong><p>Up to four familiar characters and two that need another look.</p><button class="btn" onclick="labStart('comeback')">Welcome-back set</button></section>`:''}<details class="lab-more"><summary>More activities &amp; study tools</summary><div class="lab-activity-grid">${['ear','homophones','boss','words','comeback'].map(labActivityTile).join('')}<button class="lab-activity" onclick="labOpenPaper()"><span class="lab-tile-icon">${icon('write')}</span><strong>Writing lab</strong><small>Keep writing with Next copy. Replay or save your strokes.</small>${icon('arrow')}</button></div><div class="lab-inline"><button onclick="labOpenFamilies()">Component families</button><button onclick="labOpenWords()">Word trail</button><button onclick="labVoiceSearch()">${icon('sound')} Say a word to find it</button></div></details>`);labApplySkin();cleanSyncHeaderBuddy();
}

function labLookup(ch){if(currentView==='labplay'&&labRun&&!labRun.feedback){labRun.usedHint=true;labCheckpoint()}if(cardByChar[ch])openCleanStudy(ch,'usage');else openComponentCard(ch)}
function labClickable(zh){return [...zh].map(ch=>/[\u3400-\u9fff]/.test(ch)?`<button class="lab-inline-char" lang="zh" data-ch="${esc(ch)}" onclick="labLookup(this.dataset.ch)">${esc(ch)}</button>`:esc(ch)).join('')}
function labComicArt(scene,index){const mood=['thinking','happy','ready'][index%3],starter=starterData();return `<div class="lab-comic-scene place-${scene.place}" aria-hidden="true"><span class="lab-scene-sun"></span><span class="lab-scene-hill"></span><span class="lab-scene-building"></span><span class="lab-scene-person person-eric"><i></i></span><span class="lab-scene-person person-lin"><i></i></span>${starter?`<span class="lab-scene-pet">${companionReactionArt(mood)}</span>`:''}</div>`}
function labSceneMarkup(q,r){const scene=q.scene,index=Number(q.item.split('#')[1]),translated=r.usedHint&&r.helpKind==='translation',zh=labZh(scene.zh,scene.zhTraditional);return `<article class="lab-story-scene ${q.kind==='comic'?'is-comic':''}">${q.kind==='comic'?labComicArt(scene,index):''}<div class="lab-scene-heading"><span>${esc({message:'Message',menu:'Menu',sign:'Sign',schedule:'Schedule',conversation:'Conversation'}[scene.place])}</span><span>${esc(scene.speaker)} · scene ${index+1} / 3</span></div><div class="lab-scene-text ${scene.place==='menu'||scene.place==='schedule'?'lab-document':''}" lang="zh">${labClickable(zh)}</div>${translated?`<div class="lab-scene-translation"><p>${esc(scene.py)}</p><p>${esc(scene.en)}</p></div>`:''}<div class="lab-inline"><button onclick="labHear()">${icon('sound')} Sentence audio</button><button onclick="labPreviewSceneWords()">Words in this scene</button><button onclick="labHelp('translation')">Pinyin &amp; translation <kbd>H</kbd></button></div></article>`}
function renderLabRun(){
 if(!labRun||labRun.course!==selectedCourseId){if(!labResume())navigate('lab');return}const r=labRun;if(r.done)return renderLabComplete();const q=labCurrent();if(!q){labData().runs[selectedCourseId]=null;save();toast('This exercise is unavailable. Choose another activity.');return navigate('lab')}
 setPracticeViewport(true);if(q.kind==='writing'&&inkPassed(r)&&!r.feedback)return labResolve(true);const feedback=r.feedback,choices=q.choices||[],token=r.id,pos=r.pos;
 let stimulus='';
 if(q.scene)stimulus=labSceneMarkup(q,r);
 else if(q.kind==='parts'){
  const picked=q.parts.map((_,i)=>r.partChoices[i]!==undefined?q.choices[r.partChoices[i]]:'?'),names=q.layout==='left-right'?['Left','Right']:q.layout==='top-bottom'?['Top','Bottom']:['Outside','Inside'];
  stimulus=`<div class="lab-construction"><div class="lab-build-slots layout-${q.layout}" aria-label="${names.join(' then ')} components">${picked.map((part,i)=>`<span class="lab-build-part part-${i}" lang="zh">${esc(feedback?q.parts[i]:part)}<small lang="en">${names[i]||'Next part'}</small></span>`).join('')}</div>${feedback?`<span class="lab-build-equals" aria-hidden="true">=</span><button class="lab-assembled" lang="zh" data-ch="${esc(q.answer)}" onclick="labLookup(this.dataset.ch)" aria-label="Look up ${esc(q.answer)}">${esc(q.answer)}</button>`:''}</div><div class="lab-parts-instructions"><span>${feedback?'Compare the parts with the finished character.':'Choose '+names.map(n=>n.toLowerCase()).join(', then ')+'.'}</span>${!feedback?`<button class="textbtn" ${r.partChoices.length?'':'disabled'} onclick="labUndoPart('${token}',${pos})">Undo part</button><button class="textbtn" ${r.partChoices.length?'':'disabled'} onclick="labUndoPart('${token}',${pos},true)">Reset</button>`:''}</div>`;
 }else if(q.kind==='transform')stimulus=`<div class="lab-transform"><span lang="zh">${esc(q.from)}</span><span>${icon('arrow')}</span><span lang="zh" class="${feedback?'lab-transformed':''}">${feedback?esc(q.answer):'?'}</span></div>`;
 else if(q.kind==='fonts')stimulus=`<div class="lab-font-glyph font-${q.font}" lang="zh">${esc(q.glyph)}</div><p class="lab-stimulus-caption">${['Serif','Sans serif','Kai style when installed'][q.font]}</p>`;
 else if(q.kind==='cloze')stimulus=`<p class="lab-cloze" lang="zh">${labClickable(q.sentence)}</p><p class="lab-stimulus-caption">Missing character: ${esc(q.meaning)}</p>`;
 else if(q.kind==='ear')stimulus=`<button class="btn lab-listen" onclick="labHear()">${icon('sound')} Play audio <kbd>L</kbd></button>`;
 else if(q.kind==='writing')stimulus=`<p class="lab-writing-meaning">${esc(q.meaning)}</p><button class="btn lab-listen" onclick="labHear()">${icon('sound')} Character audio <kbd>L</kbd></button>${feedback?`<div class="ink-checked" lang="zh">${esc(q.answer)}</div>`:inkMarkup(inkContext())}`;
 else if(q.kind==='recall')stimulus=feedback?'':`<form class="lab-recall-form" onsubmit="event.preventDefault();labSubmitRecall($('lab-recall-input').value,'${token}',${pos})"><label for="lab-recall-input">Type its reading in pinyin</label><input id="lab-recall-input" class="input" autocapitalize="none" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="e.g. pengyou" onkeydown="labRecallKey(event,'${token}',${pos})"><p>Tones and spaces are optional. Use ü, v, or u: for ü.</p>${labWordRecentlySeen(q.wordZh)||r.queue[pos].assisted?'<p class="lab-recently-seen">Recently viewed · this check will count as helped practice.</p>':''}</form>`;
 else if(q.context)stimulus=`<div class="lab-deck-context"><p>${labClickable(labZh(q.context))}</p><button class="textbtn" onclick="labHearSentence()">${icon('sound')} Sentence audio</button></div>`;
 const ability=labActiveAbilities().find(a=>a.skill===q.skill),word=['words','deck','recall'].includes(q.kind),rewardNote=feedback?(feedback.xp?'+'+feedback.xp+' practice XP':!feedback.correct?'This item will return for another try.':feedback.helped?'Helped practice · try it independently on a later day.':'Already checked today, or today’s practice XP limit is reached.'):'',feedbackNote=q.kind==='recall'?'Read & type · '+labDeckStatus(q.item):q.skill;
 const explanation=feedback?`<div class="lab-answer-feedback ${feedback.correct?'correct':'incorrect'}" role="status"><div class="lab-feedback-heading">${icon(feedback.correct?'check':'repeat')}<strong>${feedback.correct?(feedback.helped?'Correct with help':'Correct'):'Let’s check it'}</strong></div><p><span lang="${q.kind==='recall'?'zh-Latn':word||q.scene&&q.kind!=='dialogue'?'en':'zh'}">${esc(q.answer)}</span>${q.explanation?' · '+esc(q.explanation):''}</p>${q.evidence?`<blockquote lang="zh">${esc(labZh(q.evidence,labTraditionalEvidence(q)))}</blockquote>`:''}<small>${esc(rewardNote)}</small>${word?`<div class="lab-inline"><button onclick="labHear()">${icon('sound')} Word audio</button></div>`:''}${q.kind==='recall'&&q.context?`<details class="lab-more"><summary>Usage &amp; example</summary><p lang="zh">${labClickable(labZh(q.context))}</p><button class="textbtn" onclick="labHearSentence()">${icon('sound')} Sentence audio</button></details>`:''}</div>`:'';
 $('view').innerHTML=`<div class="lab-run"><header class="lab-run-top"><button class="textbtn" onclick="labCheckpoint();navigate('lab')">${icon('pause')} Pause</button><span>${esc(LAB_MODES[r.mode][0])}<b>${pos+1} / ${r.queue.length}</b></span><button class="iconbtn" aria-label="Activity keyboard controls" onclick="labShowHelp()">${icon('help')}</button></header><div class="progress" role="progressbar" aria-label="Chapter run progress" aria-valuemin="0" aria-valuemax="${r.queue.length}" aria-valuenow="${pos}"><span style="width:${pos/r.queue.length*100}%"></span></div><section class="lab-exercise"><div class="lab-exercise-label"><span>${esc(feedbackNote)}</span><span>${esc(lessonLabel(r.lesson))}</span></div><h1 class="${word?'lab-word-title':''}" lang="${word?'zh':'en'}">${esc(q.title)}</h1>${stimulus}${!['writing','recall'].includes(q.kind)?`<div class="lab-answer-grid ${q.kind==='parts'?'lab-parts-choices':''}">${choices.map((choice,i)=>`<button class="${feedback?(q.kind==='parts'?'':i===q.correct?'correct':i===feedback.chosen?'incorrect':''):''}" ${feedback||q.kind==='parts'&&r.partChoices.includes(i)?'disabled':''} onclick="${q.kind==='parts'?'labPart':'labAnswer'}(${i},'${token}',${pos})"><span ${/[\u3400-\u9fff]/.test(choice)?'lang="zh"':''}>${esc(choice)}</span><kbd>${i+1}</kbd></button>`).join('')}</div>`:''}${!feedback&&q.kind!=='writing'?`<div class="lab-help-row"><button class="textbtn" onclick="labHelp()">${q.kind==='recall'?'Reveal reading':'Hint'} <kbd>H</kbd></button>${word?`<button class="textbtn" onclick="labHear()">${icon('sound')} Word audio <kbd>L</kbd></button>`:''}${ability&&!r.abilityUsed?`<button class="textbtn" onclick="labUseAbility('${ability.id}')">${icon('flame')} ${esc(ability.name)}</button>`:''}</div>${r.usedHint?`<p class="lab-hint" role="status">${esc(labHintText(q))}</p>`:''}`:''}${explanation}</section><footer class="lab-run-actions">${feedback?`<button class="btn primary" onclick="labNext('${token}',${pos})">${pos===r.queue.length-1?'Finish run':'Continue'} ${icon('arrow')} <kbd>Enter</kbd></button>`:q.kind==='writing'?'<button class="btn" onclick="labResolve(false)">Skip writing check <kbd>1</kbd></button>':q.kind==='recall'?`<button class="btn primary" onclick="labSubmitRecall($('lab-recall-input').value,'${token}',${pos})">Check reading ${icon('check')} <kbd>Enter</kbd></button>`:`<p>${q.kind==='parts'?'Select the parts.':'Choose an answer.'} <kbd>1–${choices.length}</kbd></p>`}</footer></div>`;
 if(q.kind==='writing'&&!feedback)inkMount();labCheckpoint();cleanSyncHeaderBuddy();
}

function renderLabComplete(){
 setPracticeViewport(false);const r=labRun,independent=Math.max(0,r.right-r.helped),missed=[...new Set(r.misses)],next=labAdaptiveMode();
 $('view').innerHTML=labShell('Run complete',`<section class="lab-complete"><div class="lab-complete-art">${cleanBuddyEnabled()?companionReactionArt('celebrate'):icon('check')}</div><span class="eyebrow">${esc(lessonLabel(r.lesson))}</span><h2>${independent} independent answers</h2><p>${r.right} / ${r.queue.length} correct · ${r.helped} with help</p><div class="lab-completion-facts"><div><strong>${new Set(r.queue.map(d=>labQuestion(d,r)?.skill).filter(Boolean)).size}</strong><span>skills practiced</span></div><div><strong>${missed.length}</strong><span>items to revisit</span></div></div><div class="lab-complete-actions">${missed.length?`<button class="btn primary" onclick="labRetryMisses('${r.id}')">Retry ${missed.length} missed ${missed.length===1?'item':'items'} ${icon('repeat')}</button><button class="btn" onclick="labStart('${next.mode}','${r.lesson}')">${esc(LAB_MODES[next.mode][0])} ${icon('arrow')}</button>`:`<button class="btn primary" onclick="labStart('${next.mode}','${r.lesson}')">${esc(LAB_MODES[next.mode][0])} ${icon('arrow')}</button>`}<button class="textbtn" onclick="navigate('lab')">Back to chapter practice</button></div>${missed.length?`<details class="lab-more"><summary>Review the missed items</summary><div class="lab-missed-list">${missed.map(item=>{const c=cardByChar[item];return c?`<button class="btn" data-ch="${esc(item)}" onclick="labLookup(this.dataset.ch)">${esc(han(c))} · ${esc(c.pinyin)}</button>`:`<span>${esc(labQuestion(r.queue.find(d=>d.item===item),r)?.answer||'Story decision')}</span>`}).join('')}</div><p>Immediate retries are helped practice. Return on a later day to check what you remember independently.</p></details>`:''}<p class="small muted">${esc(next.reason)}</p></section><div class="lab-footer"><button class="textbtn" onclick="navigate('labskills')">Skill map</button><button class="textbtn" onclick="navigate('labcamp')">Companion camp</button><button class="textbtn" onclick="labOpenPaper()">Writing lab</button></div>`);
}

function labShowHelp(){studyModal('<h2>Practice controls</h2><p>1–4 chooses an answer. Read & type checks accept pinyin with or without tone marks; Enter submits the input. In component puzzles, choose parts in their spatial order. Enter continues after feedback. H requests help; L plays audio only when pressed.</p><p>Component selections can be undone before the final part. Writing: complete the expected strokes to answer. Backspace restarts, 1 skips. Correct feedback is practice evidence; choice games do not grant character mastery. Hints, lookups, rejected strokes, and companion abilities count as help.</p><p>Pause saves this run separately from your character/writing session. The app still opens at Home.</p>')}
function labOpenFamilies(){const id=labLesson(),pool=labShapePool('parts',id),groups={};for(const p of pool)for(const part of p.parts){const a=groups[part]??=[];if(!a.some(x=>x.id===p.id))a.push(p)}const families=Object.entries(groups).sort((a,b)=>b[1].length-a[1].length);studyModal(`<h2>Component families</h2><p>Explore a part, then build the characters that share it.</p><div class="lab-families">${families.slice(0,20).map(([part,items])=>`<section><button class="lab-family-part" data-ch="${esc(part)}" onclick="labLookup(this.dataset.ch)">${esc(part)}<small>${esc(partName(part))}</small></button><div>${items.map(p=>`<button data-id="${p.id}" onclick="labStart('parts','${id}',{items:[this.dataset.id],assisted:true});closeStudioDialogs()">${esc(p.target)}</button>`).join('')}</div></section>`).join('')}</div>${!families.length?'<p>No suitable structural puzzles in this script and lesson yet.</p>':''}`)}
function labOpenWords(){const id=labLesson(),words=labWordNodes(id);studyModal(`<h2>Word trail</h2><p>Studied characters open a word for practice. Knowing the parts does not automatically mean you know the word.</p><button class="btn primary" onclick="closeStudioDialogs();labStart('words','${id}')">Practice open words</button><div class="lab-word-board">${words.map(w=>`<button class="${w.unlocked?'is-open':''}" data-word="${esc(w.zh)}" onclick="labWordPreview(this.dataset.word)"><strong lang="zh">${esc(labZh(w.zh))}</strong><span>${esc(w.py)}</span><small>${w.parts.filter(ch=>state.cards[ch]?.seen).length} / ${w.parts.length} parts studied · ${w.unlocked?'Ready to practice':'Explore parts'}</small></button>`).join('')}</div>`)}
function labWordPreview(word){const w=labWordNodes(labLesson()).find(w=>w.zh===word);if(!w)return;studyModal(`<h2 lang="zh">${labClickable(labZh(w.zh))}</h2><p>${esc(w.py)} · ${esc(w.en)}</p><button class="btn" data-word="${esc(w.zh)}" onclick="speak(this.dataset.word)">${icon('sound')} Word audio</button><p>Explore its characters:</p><div class="row">${w.parts.map(ch=>`<button class="btn" data-ch="${ch}" onclick="labLookup(this.dataset.ch)">${esc(text(ch))}</button>`).join('')}</div><p class="small muted">Opening or hearing this word does not count as recall.</p>`)}
function renderLabSkills(){setPracticeViewport(false);const data=labData(),records=data.history.filter(r=>r.course===selectedCourseId),retained=data.retained.length;const body=`<p class="muted">Your ${uniqueCards().filter(familiar).length} familiar characters in this course carry forward. The skill accuracy below records checked practice from this update. Independent correct answers are tracked separately from answers with help. These are practice results, not proficiency scores.</p><div class="lab-skill-grid">${LAB_SKILLS.map(skill=>{const s=labSkillSummary(skill);return `<section class="lab-skill"><h2>${esc(skill[0].toUpperCase()+skill.slice(1))}</h2><strong>${s.attempts?s.percent+'%':'No checks yet'}</strong><div class="progress"><span style="width:${s.percent}%"></span></div><p>${s.correct} independent correct / ${s.attempts} attempts · ${s.helped} with help</p><small>${s.items} distinct items answered independently</small></section>`}).join('')}</div><section class="lab-retention"><h2>Remembered later</h2><p><strong>${retained}</strong> items recalled on at least three separate days spanning a week.</p><div class="row">${[['first','First roots',1],['five','Growing roots',5],['twenty','Deep roots',20]].map(([id,label,n])=>`<span class="lab-retention-badge ${retained>=n?'earned':''}">${icon(retained>=n?'check':'clock')} ${label} · ${n}</span>`).join('')}</div></section><details class="lab-more"><summary>Recent chapter runs</summary><div class="lab-history">${records.slice(-12).reverse().map(r=>`<div><strong>${esc(LAB_MODES[r.mode][0])}</strong><span>${esc(lessonLabel(r.lesson))} · ${r.right}/${r.total} correct · ${r.helped} helped</span></div>`).join('')||'<p>No chapter runs yet.</p>'}</div></details>`;$('view').innerHTML=labShell('Your skill map',body,'labskills')}
function renderLabAlbum(){setPracticeViewport(false);const chars=uniqueCards().map(c=>c.character),data=labData(),items=chars.filter(ch=>data.mistakes[ch]||state.quizMisses[ch]||state.memoryNotes[ch]||data.images[ch]).sort((a,b)=>(data.mistakes[b]?.last||state.quizMisses[b]||0)-(data.mistakes[a]?.last||state.quizMisses[a]||0));$('view').innerHTML=labShell('Your mistake album',`<p class="muted">Keep the differences you want to remember: a drawing, a note, or your own image.</p>${items.length?`<div class="lab-album-grid">${items.map(ch=>labAlbumCard(ch)).join('')}</div>`:`<section class="lab-empty"><h2>No difficult characters recorded yet</h2><p>Missed answers will appear here. You can also choose a character to add a personal memory.</p></section>`}<div class="lab-footer"><label>Add a character<select id="lab-album-char">${uniqueCards().map(c=>`<option value="${c.character}">${esc(han(c)+' · '+c.pinyin)}</option>`).join('')}</select></label><button class="btn" onclick="labAddAlbum($('lab-album-char').value)">Add memory</button><button class="btn" onclick="startSession('weak')">Practice difficult cards</button></div>`,'labalbum')}
function labAlbumCard(ch){const c=courseCard(ch),m=labData().mistakes[ch],img=labData().images[ch];return `<article class="lab-album-card"><div class="lab-album-title"><button data-ch="${ch}" onclick="labLookup(this.dataset.ch)" lang="zh">${esc(han(c))}</button><div><strong>${esc(c.pinyin)}</strong><p>${esc(c.meaning)}</p></div></div>${m?.drawing?.length?labDrawingSvg(m.drawing):''}${img?`<img src="${img}" alt="Your memory image for ${esc(han(c))}" loading="lazy">`:''}<label>A cue that works for you<textarea maxlength="300" data-ch="${ch}" oninput="labSaveNote(this.dataset.ch,this.value)">${esc(state.memoryNotes[ch]||'')}</textarea></label><div class="lab-inline"><button data-ch="${ch}" onclick="labOpenPaper(this.dataset.ch)">Write it</button>${m?.drawing?.length?`<button data-ch="${ch}" onclick="labData().mistakes[this.dataset.ch].drawing=[];save();renderLabAlbum()">Remove drawing</button>`:''}<button data-ch="${ch}" onclick="labAddImage(this.dataset.ch)">${img?'Change':'Add'} my image</button>${img?`<button data-ch="${ch}" onclick="labRemoveImage(this.dataset.ch)">Remove image</button>`:''}</div></article>`}
function labAddAlbum(ch){if(!cardByChar[ch])return;labData().mistakes[ch]??={count:0,last:Date.now(),skill:'recognition',note:'',drawing:[],model:false};save();renderLabAlbum()}
function labSaveNote(ch,value){if(!cardByChar[ch])return;const note=labText(value,300);if(note)state.memoryNotes[ch]=note;else delete state.memoryNotes[ch];save()}
function labAddImage(ch){if(!cardByChar[ch])return;const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{const f=input.files?.[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8e6)return toast('Choose a JPEG, PNG, or WebP image smaller than 8 MB.');try{const url=URL.createObjectURL(f),img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});URL.revokeObjectURL(url);const canvas=document.createElement('canvas'),scale=Math.min(1,360/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.65),others=Object.entries(labData().images).filter(([key])=>key!==ch).reduce((n,[,s])=>n+s.length,0);if(data.length>60000||others+data.length>180000)return toast('This image is too large, or your saved image space is full. Remove an image and try again.');labData().images[ch]=data;save();if(currentView==='labalbum')renderLabAlbum()}catch{toast('Could not open that image. Try another file.')}};input.click()}
function labRemoveImage(ch){delete labData().images[ch];save();renderLabAlbum()}
function labDrawingSvg(strokes){return `<svg class="lab-drawing-preview" viewBox="0 0 100 100" role="img" aria-label="Your handwriting"><path d="M50 0V100M0 50H100" class="lab-grid-line"/>${strokes.map(stroke=>`<polyline points="${stroke.map(([x,y])=>(x*100).toFixed(1)+','+(y*100).toFixed(1)).join(' ')}"/>`).join('')}</svg>`}

function labTraditionalEvidence(q){if(!q.scene?.zhTraditional||!q.evidence)return '';const index=q.scene.zh.indexOf(q.evidence);return index>=0&&q.scene.zh.length===q.scene.zhTraditional.length?q.scene.zhTraditional.slice(index,index+q.evidence.length):''}
